architecture.h4_f:
msg = CBOR{v:1, teksto, sungbat_iti, naipatulod_iti}
ct = AES-GCM-256-Encrypt (k, nonce, msg, aad = id_ti_kuarto)
POST /api/kuarto/{id}/mensahe {ciphertext: hex (ct), nonce: hex}

auth.h1_f:
POST /api/panagpabigbig/panagrehistro
  { nagan ti agar-aramat, password, x25519_tulbek_ti_publiko, nagan_ti_panangiparang, telepono?, email?, avatar_emoji }

Sungbat 201 Naparsua:
  { access_token, refresh_token, id_ti_agar-aramat, nagan ti agar-aramat, ... }

auth.h3_f:
access_token a karga ti pagbayad:
  { sub: user_id, jti: device_id, tipo: "panagserrek", exp: ita + 15min }
refresh_token a karga ti pagbayad:
  { sub: user_id, jti: device_id, tipo: "agpabaro", exp: ita + 30d }

HS256-napirmaan iti 64-byte a sekreto ti node manipud iti .env

rooms.h6_f:
pseudo_ti_mangipatulod = HMAC-SHA256 (siled_pseudo_salt, id_ti_mangipatulod) [:16] // 32 hex
ciphertext = AES-GCM-Encrypt ( tulbek_ti_kuarto, nonce, CBOR_payload, aad = id_ti_kuarto)

Fan-out frame: { tipo:"m", kuarto, msg:{id, ct, nonce, sender_pseudo, naipatulod_iti} }

files.h2_f:
init POST /api/files/resumible/init {nagan ti papeles, kadakkel, pammalubos_ti_kadakkel_ti_chunk}
            ← {id_ti_panag-upload, kadakkel_ti_chunk}
chunk PUT /api/files/mabalin manen/{id_ti_i-upload}/chunk/{offset} <ct bytes>
            ← 204 nga
iringpas POST /api/files/mabalin manen/{upload_id}/ileppas {plain_blake3}
            ← 201 {id_ti_file, url} .
TTL iti saan a nalpas: 24 h

presence.h1_f:
kliyente: iti umuna a panangi-keystroke → ipatulod ti {tipo:"t", estado:"rugi"}
         awanen ti mangipatulod iti 3 s malaksid no agbaliw ti estado
         10 s kalpasan ti naudi a panangi-keystroke → ipatulod {tipo:"t", estado:"agsardeng"}
receiver: auto-stop 10 s kalpasan ti naudi a "panagrugi" no awan ti simmangpet a "panagsardeng".

presence.h2_f:
POST /api/kuarto/{id}/basaen { maudi_a_mabasa_id_ti_mensahe }

no ti user.hides_receipts:
   saankayo nga agtultuloy; saan nga agbrodkas
   saan nga agserbi kadagiti resibo ti dadduma iti daytoy nga agus-usar
else:
   UPSERT dagiti_resibo_basaen VALUES (id_ti_kuarto, id_ti_agar-aramat, id_ti_mensahe, NOW())
   broadcast {tipo:"r", kuarto, agar-aramat, mensahe_id}

calls.h1_f:
POST /api/awag/{id_ti_kuarto}/rugi {video, audio} → call_id
WS broadcast {tipo:"c", kita:"awisen", call_id}
WS broadcast {tipo:"c", kita:"itukon", sdp}
WS broadcast {tipo:"c", kita:"sungbat", sdp}
WS brodkas {tipo:"c", kita:"kandidato",yelo} × N
POST /api/dagiti panagtawag/{id_ti_awag}/pagpatingga

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-saludsod {nagan: x.vortexx.sol}
ECH: ClientHello.extensions += na-enkripto_sni (tulbek_ti_publiko_manipud_ti_rekord_ti_HTTPS)
DGA: dominio (t) = base32( SHA256(bukel ∥ YYYY-MM-DD) )[:16] + ".pagarigan".

push.h4_f:
iOS NSE: didReceive (kiddaw) { decrypt (kiddaw.linaon.Impormasion ti agar-aramat) }
Android FCM: onMessageReceived (adayo a Mensahe) { decrypt (adayo a Mensahe.datos) }
Web SW: self.addEventListener ('iduron', e => dekripto (e.datos))

bots.h1_f:
mangparnuay: POST /api/bots {nagan ti agar-aramat, nagan_ti_iparang, kodigo}
          → {bot_id, token, tulbek ti pub}
run: iti proseso (coroutine iti uneg ti node) .
      OR akinruar (atiddog-a-panagbutos /api/bots/{id}/panagpabaro, token-auth'd)
mensahe: {teksto, pirma: Ed25519-Pirma (bot_priv, kanonikal_msg)}

security.h4_f:
canary.txt (inaldaw): .
  {petsa, sig: Ed25519-Sign (priv_ti_panangiruar, petsa)}
kliyente paneknekanna → awan wenno saan nga umiso ⇒ kompromiso ti masuspetsa

emerhensia:
  admin POST /api/admin/waswas-amin {rason}
  node broadcasts {tipo:"n", pasamak:"kompromiso", rason}
  kliyente punasen dagiti tulbek, piliten ti re-bootstrap

login.h3_f:
{
  "nagan ti agar-aramat": "alice", .
  "password": "umiso nga staple ti bateria ti kabalio",
  "totp": "123456" // kasapulan no ti 2FA ket napalubosan
} .

apns.h1_f:
POST https://api.push.apple.com/3/alikamen/<token_ti_alikamen>
Dagiti ulo: apns-topiko: <bundle_id>, apns-push-tipo: alerto, apns-collapse-id: kuarto:42
Bagi: {aps: {alerto: {titulo, bagi}}, datos: <naselioan>}

bmp.h1_f:
id_kahon_koreo = HKDF (tulbek_ti_umawat, impormasion = "bmp-v1", len = 32)
Deposito: POST /bmp/deposito {id_kahon ti koreo, blob ≤1MB}
Pickup: GET /bmp/mensahe (na-auth'd) .

controller.h1_f:
GET /v1/integridad → {kasasaad, napirmaan_ babaen, naipada, saan a naipada, ...}
GET /v1/salun-at → {kasasaad, bersion, pubkey, estadistika}
GET /v1/dagiti panagserrek → [{protokolo, url}, ...]
GET /v1/sarming → [url_ti_kontrolador, ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/proyekto/<proyekto>/mensahe:ipatulod
Autorisasion: Agawit <oauth2_token>
Bagi: {mensahe: {token: <alikamen>, datos: {...naselioan...}, android: {collapse_key}}}

federation.h1_f:
sobre = {gubuayan_nodo, target_user, makin-uneg_ct, makin-uneg_nonce, naipatulod_iti}
sig = Ed25519-Pirma (gubuayan_priv, CBOR (sobre))
POST /pederasion/itulod {sobre, sig}
B paneknekanna: agpirma a maibusor kadagiti pederasion[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE dagiti mensahe_fts USING fts5(
  linaon, -- tokenised a kolum
  id_ti_kuarto UNINDEXED, .
  tokenize = 'unicode61 ikkaten_ti_diakritiko 2'.
);
saludsod: SELECT rowid FROM mensahe_fts WHERE linaon MATCH 'foo'.

gravitix.h1_f:
on /start { emit "Maabrasa, {ctx.umuna_a_nagan}" }
iti /inayon ti <item> { .
  estado.lista = (estado.listaan wenno []) + [ctx.args.item].
  emit "Nainayon: {ctx.args.item}"
} .

vapid.h1_f:
VAPID dagiti tulbek: Ed25519 a paris ti tulbek iti tunggal maysa a nodo
karatula JWT: {aud: nagtaudan_ti_serbisio_ti_iduron, exp: ita + 12h, sub: mailto:ops@pagarigan}
iduron dagiti ulo ti kiddaw: Autorisasion: vapid t=<jwt>, k=<vapid_public_key>
